return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'ne_NP','project-id-version'=>'Babilim 1.2.0','pot-creation-date'=>'2026-11-05T19:51:02+00:00','po-revision-date'=>'2026-11-05T19:51:02+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'तपाईंको साइटमा पहिले नै स्थापना गरिएका प्लगइन र थिमहरूका लागि हराइरहेका अनुवादहरू भर्छ।','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'त्यो अपलोड स्क्रिन पुरानो भइसकेको थियो: त्यसपछि फरक अपलोड तयार पारिएको छ। केही पनि पठाइएको छैन। हालको अपलोड अनुवादहरूको सूचीबाट समीक्षा गर्नुहोस्।','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'निःशुल्क सेवा योजनाले प्रत्येक साइटलाई प्लगइन र थिमहरूका लागि सीमित संख्यामा स्लटहरू दिन्छ; Babilim सक्षम गरेपछि प्रयोगमा रहेका स्लटहरू सेटिङहरूमा देखाइन्छ।','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'अनुवादको अनुरोध गर्दा यो प्लगइन वा थिमलाई यस साइटको निःशुल्क सेवा योजनाको एउटा स्लटमा राखिन्छ (सीमा थिमका लागि %1$d र प्लगइनका लागि %2$d हो), यदि त्यसमा पहिले नै स्लट छैन भने। स्लट प्रयोगमा नै रहन्छ, र असफल अनुवादले त्यसलाई खाली गर्दैन।','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'अनुवादको अनुरोध गर्दा यो प्लगइन वा थिमलाई यस साइटको निःशुल्क सेवा योजनाको एउटा स्लटमा राखिन्छ, यदि त्यसमा पहिले नै स्लट छैन भने। स्लट प्रयोगमा नै रहन्छ, र असफल अनुवादले त्यसलाई खाली गर्दैन।','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one (the limit is %1$d for themes and %2$d for plugins). A slot stays used, and a failed translation does not free it. Continue?'=>'यदि यो प्लगइन वा थिम यस साइटको निःशुल्क सेवा योजनाको कुनै स्लटमा अझै छैन भने, अनुवादको अनुरोध गर्दा त्यसलाई एउटा स्लटमा राखिन्छ (सीमा थिमका लागि %1$d र प्लगइनका लागि %2$d हो)। स्लट प्रयोगमा नै रहन्छ, र असफल अनुवादले त्यसलाई खाली गर्दैन। जारी राख्नुहुन्छ?','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one. A slot stays used, and a failed translation does not free it. Continue?'=>'यदि यो प्लगइन वा थिम यस साइटको निःशुल्क सेवा योजनाको कुनै स्लटमा अझै छैन भने, अनुवादको अनुरोध गर्दा त्यसलाई एउटा स्लटमा राखिन्छ। स्लट प्रयोगमा नै रहन्छ, र असफल अनुवादले त्यसलाई खाली गर्दैन। जारी राख्नुहुन्छ?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'यस नेटवर्कको %1$d साइट प्लगइन मेटाउँदा आफ्नो Babilim पहिचान मेटाउने गरी सेट गरिएको छ। त्यस साइटमा जोडिएको सशुल्क इजाजतपत्र त्यसपछि स्वतः पुनःप्राप्त गर्न सकिँदैन; तपाईंले %2$s मा Babilim सहायतासँग सम्पर्क गर्नुपर्नेछ। पहिचान राख्न, रद्द गर्नुहोस् थिच्नुहोस्, त्यस साइटको Babilim सेटिङहरूमा "अनइन्स्टल गर्दा सबै Babilim डेटा मेटाउनुहोस्" को चिह्न हटाउनुहोस्, र फेरि निष्क्रिय गर्नुहोस्। जे भए पनि निष्क्रिय गर्ने?' . "\0" . 'यस नेटवर्कका %1$d साइटहरू प्लगइन मेटाउँदा आफ्नो Babilim पहिचान मेटाउने गरी सेट गरिएका छन्। ती साइटहरूमा जोडिएका सशुल्क इजाजतपत्रहरू त्यसपछि स्वतः पुनःप्राप्त गर्न सकिँदैन; तपाईंले %2$s मा Babilim सहायतासँग सम्पर्क गर्नुपर्नेछ। पहिचानहरू राख्न, रद्द गर्नुहोस् थिच्नुहोस्, प्रत्येक साइटको Babilim सेटिङहरूमा "अनइन्स्टल गर्दा सबै Babilim डेटा मेटाउनुहोस्" को चिह्न हटाउनुहोस्, र फेरि निष्क्रिय गर्नुहोस्। जे भए पनि निष्क्रिय गर्ने?','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s गर्नुपर्ने केही छैन।','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s। भाषा छान्नुहोस्।','%d failed'=>'%d असफल भयो' . "\0" . '%d असफल भए','%d not yet tried'=>'%d अझै प्रयास गरिएको छैन' . "\0" . '%d अझै प्रयास गरिएको छैन','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'%d रिपोर्ट प्रतीक्षामा छ। "सधैं साझा गर्नुहोस्" र "साझा नगर्नुहोस्" ती सबैमा लागू हुन्छ।' . "\0" . '%d रिपोर्टहरू प्रतीक्षामा छन्। "सधैं साझा गर्नुहोस्" र "साझा नगर्नुहोस्" ती सबैमा लागू हुन्छ।','%d skipped'=>'%d वटा छोडियो' . "\0" . '%d वटा छोडिए','%d succeeded'=>'%d सफल भयो' . "\0" . '%d सफल भए','%d to install'=>'स्थापना गर्न %d' . "\0" . 'स्थापना गर्न %d','(a public key generated for this site)'=>'(यस साइटका लागि उत्पन्न गरिएको सार्वजनिक कुञ्जी)','(detected)'=>'(पत्ता लागेको)','(generic codes and coordinates only)'=>'(सामान्य कोड र निर्देशाङ्क मात्र)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'%1$s मा एउटा सफाइ रोकियो: %2$s। केही पनि मेटाइएन।','A file in the component could not be read, so it was not packaged.'=>'कम्पोनेन्टमा रहेको एउटा फाइल पढ्न सकिएन, त्यसैले यसलाई प्याकेज गरिएन।','A host that serves only one PHP request at a time cannot complete this step.'=>'एकै पटकमा एउटा मात्र PHP अनुरोध सेवा गर्ने होस्टले यो चरण पूरा गर्न सक्दैन।','A part of the upload kept failing, so the upload was cancelled.'=>'अपलोडको एउटा भाग बारम्बार असफल भयो, त्यसैले अपलोड रद्द गरियो।','A translation cannot be requested for that locale on this site right now.'=>'यो साइटमा अहिले त्यो लोकेलका लागि अनुवादको अनुरोध गर्न सकिँदैन।','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'%1$s मा अर्को अनुरोधसँग अनुवाद सूचकांक (%2$s) लेखन द्वन्द्व भयो र लागू गरिएन; सबैभन्दा पछिल्लो संस्करण राखियो।','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'%1$s मा अनुवाद सूचकांक (%2$s) लेखन पूरा हुन सकेन र लागू गरिएन (%3$s)।','Account'=>'खाता','Add another language'=>'अर्को भाषा थप्नुहोस्','Advanced'=>'उन्नत','All'=>'सबै','All free-plan slots for this site are used'=>'यस साइटका सबै निःशुल्क योजनाका स्लटहरू प्रयोगमा छन्','All languages'=>'सबै भाषाहरू','Already in WordPress core'=>'पहिले नै WordPress कोरमा छ','Already installed.'=>'पहिले नै इन्स्टल गरिएको छ।','Always share'=>'सधैं साझा गर्नुहोस्','Another installation is running; try again in a moment.'=>'अर्को स्थापना चलिरहेको छ; केही क्षणपछि फेरि प्रयास गर्नुहोस्।','Automatic installs'=>'स्वचालित इन्स्टलहरू','Automatic installs are now off; turn them on again in the settings if you want them.'=>'स्वचालित इन्स्टलहरू अब बन्द छन्; चाहनुभयो भने सेटिङहरूमा गई फेरि खोल्नुहोस्।','Available'=>'उपलब्ध','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'उपलब्ध अनुवादहरू एक क्लिकमै स्थापना गर्न सकिन्छ, र हराइरहेकाहरूका लागि अनुरोध गर्न सकिन्छ। स्वचालित स्थापनाहरू सक्रिय हुँदा, तपाईंले व्यवस्थापन गर्ने भाषाहरूका लागि सेवाले उपलब्ध भनी सूचीबद्ध गरेका अनुवादहरू दिनमा दुई पटक हुने सिङ्कको समयमा स्थापना गरिन्छन्।','Available · %s'=>'उपलब्ध · %s','Babilim Settings'=>'Babilim सेटिङहरू','Babilim adds translations for every language checked here.'=>'Babilim ले यहाँ चयन गरिएका हरेक भाषाका लागि अनुवादहरू थप्छ।','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim ले वेबसाइट बाहिर अस्थायी फोल्डर पुष्टि गर्न सकेन, त्यसैले कम्पोनेन्ट प्याकेज गरिएन र केही पनि अपलोड गरिएन। wp-config.php मा BABILIM_TEMP_DIR लाई वेब रुट बाहिरको लेख्न मिल्ने फोल्डरका रूपमा परिभाषित गर्नुहोस् (उदाहरणका लागि तपाईंको साइटको सार्वजनिक डाइरेक्टरीको छेउमा रहेको, भित्र नरहेको फोल्डर), वा आफ्नो होस्टसँग सोध्नुहोस्।','Babilim could not finish checking this site.'=>'Babilim ले यो साइटको जाँच पूरा गर्न सकेन।','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim ले सक्षम गर्ने काम पूरा गर्न सकेन (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim ले यो साइट प्रमाणित गर्ने काम पूरा गर्न सकेन (सेवाले साइटमा फर्केर सम्पर्क गर्न सकेन)। दर्ता रोकिएको छ।','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim ले यो साइट प्रमाणित गर्न सकेन, त्यसैले प्रमाणीकरण सफल नभएसम्म केही पनि डाउनलोड वा इन्स्टल गरिने छैन।','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim ले यो साइट प्रमाणित गर्न सकेन, त्यसैले केही पनि डाउनलोड वा स्थापना गरिएको छैन।','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim ले यो साइटमा तपाईंको भाषाको अनुवाद नभएका प्लगइन र थिमहरू फेला पार्छ र प्रत्येकका लागि एउटा स्थापना गर्छ।','Babilim has not been enabled for this site yet.'=>'यो साइटको लागि Babilim अझै सक्षम गरिएको छैन।','Babilim has not installed any translation for this language.'=>'Babilim ले यस भाषाको लागि कुनै अनुवाद स्थापना गरेको छैन।','Babilim hit an error. Share an error report?'=>'Babilim मा त्रुटि आयो। त्रुटि रिपोर्ट साझा गर्ने?','Babilim installed %d translation automatically since your last visit.'=>'तपाईंको पछिल्लो भ्रमणदेखि Babilim ले %d अनुवाद स्वचालित रूपमा स्थापना गर्‍यो।' . "\0" . 'तपाईंको पछिल्लो भ्रमणदेखि Babilim ले %d अनुवादहरू स्वचालित रूपमा स्थापना गर्‍यो।','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim निष्क्रिय छ। थप केही पठाइँदैन; पहिले नै स्थापना गरिएका अनुवादहरू काम गरिरहन्छन्।','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim सक्षम छ: यो साइट प्रमाणित भएको छ र %d कम्पोनेन्ट भेटियो।' . "\0" . 'Babilim सक्षम छ: यो साइट प्रमाणित भएको छ र %d कम्पोनेन्टहरू भेटिए।','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim ले यो साइट सक्षम गर्दै र जाँच गर्दै छ… (पछिल्लो प्रयास: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim ले यो साइट सक्षम गर्दै र जाँच गर्दै छ… यो पृष्ठ रिलोड गर्नुहोस् वा अनुसूचित जाँच सकिने प्रतीक्षा गर्नुहोस्।','Babilim is not enabled.'=>'Babilim सक्षम गरिएको छैन।','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'प्लगइन मेटाउँदा Babilim ले यस साइटको पहिचान मेटाउने गरी सेट गरिएको छ। त्यसपछि यस साइटमा जोडिएको सशुल्क इजाजतपत्र स्वतः पुनःप्राप्त गर्न सकिँदैन; तपाईंले %s मा Babilim सहायतासँग सम्पर्क गर्नुपर्नेछ। पहिचान राख्न, रद्द गर्नुहोस् थिच्नुहोस्, Babilim सेटिङहरूमा "अनइन्स्टल गर्दा सबै Babilim डेटा मेटाउनुहोस्" को चिह्न हटाउनुहोस्, र फेरि निष्क्रिय गर्नुहोस्। जे भए पनि निष्क्रिय गर्ने?','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim को यो चरणका लागि समय सकियो र यसले अर्को जाँचमा जारी राख्नेछ।','Babilim settings'=>'Babilim सेटिङहरू','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'सेवाद्वारा Babilim सिंक अस्थायी रूपमा ढिलो गरिएको छ (दर सीमित); यसले %s पछि फेरि प्रयास गर्नेछ।','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'यो अपलोड पर्खिरहेको बेला Babilim अद्यावधिक गरियो। पुरानो प्याकेज खारेज गरियो; कृपया अपलोड फेरि पुष्टि गर्नुहोस्।','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim ले %1$s (संस्करण %2$s) बाट यी फाइलहरू अपलोड गर्नेछ: हरेक .php र .js फाइल, हरेक block.json फाइल, र यसको मुख्य फोल्डरमा रहेका readme.txt, readme.md, style.css र theme.json। यिनीहरू अनुवाद गर्नुपर्ने पाठ फेला पार्न र प्लगइन वा थिम पहिचान गर्न प्रयोग गरिन्छ।','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest उपलब्ध छैन: %s','Back'=>'पछाडि','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'यो डोमेनका लागि पहिले इजाजतपत्र किन्नुभएको थियो? चेकआउटमा प्राप्त पुनर्स्थापना कोड प्रविष्ट गर्नुहोस्।','Broken placeholder'=>'बिग्रिएको प्लेसहोल्डर','Build'=>'बिल्ड','Built'=>'निर्मित','Bulk actions apply only to the selected language of each selected component.'=>'सामूहिक कार्यहरू प्रत्येक चयन गरिएको कम्पोनेन्टको चयन गरिएको भाषामा मात्र लागू हुन्छन्।','Bulk actions apply to every matching language of each selected component.'=>'सामूहिक कार्यहरू प्रत्येक चयन गरिएको कम्पोनेन्टका सबै मिल्दा भाषाहरूमा लागू हुन्छन्।','Bulk download:'=>'सामूहिक डाउनलोड:','Bulk request:'=>'सामूहिक अनुरोध:','Bulk update:'=>'सामूहिक अपडेट:','Bundled with the plugin'=>'प्लगइनसँगै समावेश','Bundled with the theme'=>'थिमसँगै समावेश','By clicking Enable, you agree to send the information listed above to Babilim.'=>'सक्षम गर्नुहोस् थिचेर, तपाईं माथि सूचीबद्ध जानकारी Babilim लाई पठाउन सहमत हुनुहुन्छ।','By continuing you confirm that you have the right to upload this component.'=>'जारी राखेर तपाईं यो कम्पोनेन्ट अपलोड गर्ने अधिकार भएको पुष्टि गर्नुहुन्छ।','Cancel'=>'रद्द गर्नुहोस्','Category'=>'वर्ग','Check again'=>'फेरि जाँच गर्नुहोस्','Check again now'=>'अहिले फेरि जाँच गर्नुहोस्','Checkout is not available for this site right now.'=>'यो साइटको लागि अहिले चेकआउट उपलब्ध छैन।','Choose'=>'छान्नुहोस्','Choose a category…'=>'वर्ग छान्नुहोस्…','Choose a language'=>'भाषा छान्नुहोस्','Choose a language…'=>'भाषा छान्नुहोस्…','Clear filters'=>'फिल्टरहरू हटाउनुहोस्','Close'=>'बन्द गर्नुहोस्','Component'=>'कम्पोनेन्ट','Confirm'=>'पुष्टि गर्नुहोस्','Conflicting keys'=>'विवादित कुञ्जीहरू','Continue'=>'जारी राख्नुहोस्','Continue next batch (%d left)'=>'अर्को ब्याच जारी राख्नुहोस् (%d बाँकी)','Continuing…'=>'जारी राख्दै…','Could not back up %s before replacing it.'=>'%s प्रतिस्थापन गर्नुअघि ब्याकअप गर्न सकिएन।','Could not create the package archive.'=>'प्याकेज अभिलेख सिर्जना गर्न सकिएन।','Could not determine active components; the existing merged index was left unchanged.'=>'सक्रिय कम्पोनेन्टहरू निर्धारण गर्न सकिएन; विद्यमान मर्ज गरिएको सूची परिवर्तन नगरी छोडियो।','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'स्थापित प्लगइन/थिमहरू निर्धारण गर्न सकिएन; सफाइ छोडियो, केही पनि मेटाइएन।','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'सेवाबाट WordPress.org को पूर्ण लोकेल सूची लोड गर्न सकिएन, त्यसैले अहिले अरू कुनै भाषा थप्न सकिँदैन।','Could not move %s into place.'=>'%s लाई यथास्थानमा सार्न सकिएन।','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'\'%s\' को मर्ज गरिएको सूचकांक स्थानमा सार्न सकिएन; अघिल्लो प्रयोगमा रहेको सूचकांक (यदि थियो भने) आधा-अद्यावधिक अवस्थामा छोड्नुको सट्टा हटाइयो। अर्को सफल पुनर्निर्माणसम्म यस लोकेलका लागि कुनै पूर्वनिर्धारित डोमेन पूरक प्रदान गरिँदैन।','Could not open zip: %s'=>'zip खोल्न सकिएन: %s','Could not prepare %s for rollback.'=>'%s लाई रोलब्याकका लागि तयार गर्न सकिएन।','Could not read %s back after moving it into place.'=>'%s लाई स्थानमा सारेपछि फेरि पढ्न सकिएन।','Could not read: %s'=>'पढ्न सकिएन: %s','Could not restore the purchase: %s'=>'खरिद पुनर्स्थापना गर्न सकिएन: %s','Could not show a new restore code: %s'=>'नयाँ पुनर्स्थापना कोड देखाउन सकिएन: %s','Could not stage %s'=>'%s स्टेज गर्न सकिएन','Could not stage default/%s'=>'default/%s स्टेज गर्न सकिएन','Could not start checkout: %s'=>'चेकआउट सुरु गर्न सकिएन: %s','Could not verify entry count for %s'=>'%s का लागि प्रविष्टि संख्या प्रमाणित गर्न सकिएन','Could not write the downloaded package to disk.'=>'डाउनलोड गरिएको प्याकेज डिस्कमा लेख्न सकिएन।','Could not write the staged merged index.'=>'स्टेज गरिएको मर्ज गरिएको सूचकांक लेख्न सकिएन।','Current translation'=>'हालको अनुवाद','Custom overrides'=>'कस्टम ओभरराइडहरू','Danger zone'=>'खतरा क्षेत्र','Default supplement entry count mismatch.'=>'पूर्वनिर्धारित पूरक प्रविष्टि संख्या मेल खाएन।','Delete all Babilim data on uninstall'=>'अनइन्स्टल गर्दा सबै Babilim डेटा मेटाउनुहोस्','Disable Babilim'=>'Babilim असक्षम पार्नुहोस्','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Babilim असक्षम पार्ने? इन्स्टल गरिएका अनुवादहरू रहनेछन्, तर थप जाँच वा डाउनलोड चल्नेछैन।','Don\'t share'=>'साझा नगर्नुहोस्','Download'=>'डाउनलोड गर्नुहोस्','Downloaded and installed.'=>'डाउनलोड र इन्स्टल गरियो।','Downloading…'=>'डाउनलोड गर्दै…','Downloads: %1$d/%2$d (%3$s)'=>'डाउनलोडहरू: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'प्रत्येक कम्पोनेन्टको आफ्नै योगदान, प्रत्येक लोकेलको साझा पूर्वनिर्धारित डोमेन पूरकमा।','Enable Babilim'=>'Babilim सक्षम गर्नुहोस्','Enabling…'=>'सक्षम गर्दै…','English (United States)'=>'अंग्रेजी (संयुक्त राज्य अमेरिका)','Entries'=>'प्रविष्टिहरू','Entry count mismatch for %s'=>'%s का लागि प्रविष्टि संख्या मेल खाएन','Error reports'=>'त्रुटि रिपोर्टहरू','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'प्रत्येक स्थापित प्लगइन/थिम: यसको स्लग, संस्करण, टेक्स्ट डोमेन(हरू), यो wp.org सूची हो कि होइन, यसमै समावेश लोकेलहरू, र तपाईंले पहिले नै Babilim अनुवाद स्थापना गरेका लोकेलहरू।','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'यस साइटमा प्रयोगमा रहेका सबै लोकेलहरू (साइट लोकेल, स्थापित भाषा प्याकहरू, प्रयोगकर्ता लोकेलहरू, र तपाईंले म्यानुअल रूपमा थपेका कुनै पनि)। कुनै पनि लोकेललाई अरूभन्दा फरक व्यवहार गरिँदैन।','Excluded'=>'बहिष्कृत','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'अन्य नाम वा एक्स्टेन्सन भएका फाइलहरू समावेश गरिँदैनन्, न त uploads, cache, logs, backup, data, vendor, node_modules र languages फोल्डरहरू, लुकेका फाइलहरू, वा सामान्य गोप्य फाइलसँग मिल्ने नाम भएका फाइलहरू (wp-config*, .env*, *.sql, *.log, *.pem, *.key) समावेश गरिन्छन्। कोड फाइलहरूमा अझै पनि तपाईंले साझा गर्न नचाहने पाठ वा डेटा हुन सक्छ; शंका लागेमा तिनलाई जाँच गर्नुहोस्। सेवाले आइपुगेपछि फेरि त्यस्तै प्रकारका फाइलहरू हटाउँछ।','Free'=>'निःशुल्क','Free-plan slots'=>'निःशुल्क योजनाका स्लटहरू','General'=>'सामान्य','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'यो खोलिएमा, अनइन्स्टल गर्दा यस साइटको पहिचान पनि मेटिन्छ। त्यसपछि यस साइटमा जोडिएको सशुल्क इजाजतपत्र स्वतः पुनःप्राप्त गर्न सकिँदैन; त्यसलाई फिर्ता पाउन तपाईंले %s मा Babilim सहायतासँग सम्पर्क गर्नुपर्नेछ।','Included'=>'समावेश गरिएको','Included in index'=>'सूचकांकमा समावेश गरिएको','Install available translations automatically'=>'उपलब्ध अनुवादहरू स्वचालित रूपमा इन्स्टल गर्नुहोस्','Installed'=>'स्थापना गरिएको','Installed translations are kept, but no further checks or downloads will run.'=>'स्थापना गरिएका अनुवादहरू राखिन्छन्, तर थप जाँच वा डाउनलोडहरू चल्ने छैनन्।','Installed · %s'=>'स्थापना गरिएको · %s','Installed · built for %1$s, this site has %2$s'=>'स्थापना गरिएको · %1$s का लागि बनाइएको, यस साइटमा %2$s छ','Installed · built for %s'=>'स्थापना गरिएको · %s का लागि बनाइएको','Installed · built for %s, all free-plan slots for this site are used'=>'स्थापना गरिएको · %s का लागि बनाइएको, यस साइटका सबै निःशुल्क योजनाका स्लटहरू प्रयोगमा छन्','Installed · built for %s, new version failed'=>'स्थापना गरिएको · %s का लागि बनाइएको, नयाँ संस्करण असफल भयो','Installed · built for %s, new version not covered by the free service plan'=>'स्थापना गरिएको · %s का लागि बनाइएको, नयाँ संस्करण निःशुल्क सेवा योजनामा समावेश छैन','Installed · built for %s, new version scheduled'=>'स्थापना गरिएको · %s का लागि बनाइएको, नयाँ संस्करण अनुसूचित','Installed · built for %s, translating the new version…'=>'स्थापना गरिएको · %s का लागि बनाइएको, नयाँ संस्करण अनुवाद गरिँदैछ…','Installed · built for a different version'=>'स्थापना गरिएको · फरक संस्करणका लागि बनाइएको','Installed · built for a different version, all free-plan slots for this site are used'=>'स्थापना गरिएको · फरक संस्करणका लागि बनाइएको, यस साइटका सबै निःशुल्क योजनाका स्लटहरू प्रयोगमा छन्','Installed · built for a different version, new version failed'=>'स्थापना गरिएको · फरक संस्करणका लागि बनाइएको, नयाँ संस्करण असफल भयो','Installed · built for a different version, new version not covered by the free service plan'=>'स्थापना गरिएको · फरक संस्करणका लागि बनाइएको, नयाँ संस्करण निःशुल्क सेवा योजनामा समावेश छैन','Installed · built for a different version, new version scheduled'=>'स्थापना गरिएको · फरक संस्करणका लागि बनाइएको, नयाँ संस्करण अनुसूचित','Installed · built for a different version, translating the new version…'=>'स्थापना गरिएको · फरक संस्करणका लागि बनाइएको, नयाँ संस्करण अनुवाद गरिँदैछ…','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'यो सेवाको होस्टिङ प्रदायकद्वारा भण्डारण गरिन्छ र अनुवाद तयार गर्न AI मोडेलहरूद्वारा प्रशोधन गरिन्छ।','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'सबै कुरा पर्ज गर्दा वा यो प्लगइन अनइन्स्टल गर्दा मेरा आफ्नै अनुवाद ओभरराइडहरू राख्नुहोस्।','Language'=>'भाषा','Language:'=>'भाषा:','Languages'=>'भाषाहरू','Languages found on this site: %s.'=>'यो साइटमा भेटिएका भाषाहरू: %s।','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'%1$s मा पछिल्लो सफाइ: %2$d नयाँ चिन्ह लगाइयो, %3$d फाइल मेटाइयो, %4$d रेकर्ड हटाइयो।','Maintenance'=>'मर्मतसम्भार','Maintenance status is not available right now.'=>'मर्मतसम्भारको स्थिति अहिले उपलब्ध छैन।','Manifest unavailable: %s'=>'म्यानिफेस्ट उपलब्ध छैन: %s','Negation reversed'=>'नकारात्मक अर्थ उल्टिएको','No'=>'होइन','No build is available to download for this locale.'=>'यो लोकेलका लागि डाउनलोड गर्न कुनै बिल्ड उपलब्ध छैन।','No cleanup has run yet.'=>'अहिलेसम्म कुनै सफाइ चलेको छैन।','No components match these filters. %s'=>'यी फिल्टरहरूसँग मिल्ने कुनै कम्पोनेन्ट छैन। %s','No components synced yet.'=>'अहिलेसम्म कुनै कम्पोनेन्ट सिङ्क गरिएको छैन।','No installed translation matches.'=>'स्थापना गरिएको कुनै अनुवाद मेल खाँदैन।','No language is managed yet.'=>'अहिलेसम्म कुनै भाषा व्यवस्थापन गरिएको छैन।','No pending challenge for this nonce.'=>'यो नन्सका लागि कुनै विचाराधीन चुनौती छैन।','No pending challenge to verify.'=>'प्रमाणित गर्नका लागि कुनै विचाराधीन च्यालेन्ज छैन।','No plugins or themes found.'=>'कुनै प्लगइन वा थिम फेला परेन।','No previous build to roll back to.'=>'रोलब्याक गर्न कुनै अघिल्लो बिल्ड छैन।','No record for %s'=>'%s को कुनै रेकर्ड छैन','No site id is on file to rotate a token for.'=>'टोकन परिवर्तन गर्न फाइलमा कुनै साइट आईडी भेटिएन।','No — component inactive'=>'होइन — कम्पोनेन्ट निष्क्रिय छ','No — component removed'=>'होइन — कम्पोनेन्ट हटाइएको छ','No — installed version differs from the active one'=>'होइन — स्थापना गरिएको संस्करण सक्रिय संस्करणभन्दा फरक छ','Not a valid server_build_id: %s'=>'मान्य server_build_id होइन: %s','Not covered by the free service plan'=>'निःशुल्क सेवा योजनामा समावेश छैन','Not installed'=>'स्थापना गरिएको छैन','Not registered yet'=>'अहिलेसम्म दर्ता गरिएको छैन','Not supported'=>'समर्थित छैन','Not verified'=>'प्रमाणित गरिएको छैन','Note (optional)'=>'टिप्पणी (ऐच्छिक)','Nothing to choose.'=>'छान्न केही छैन।','Nothing to confirm.'=>'पुष्टि गर्न केही छैन।','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'पूर्वनिर्धारित रूपमा बन्द: प्लगइन मेटाउँदा यस साइटको पहिचान रहन्छ, ताकि पुनः इन्स्टल गर्दा त्यसलाई पुनः प्रयोग गर्न सकियोस्।','One or more served files no longer match the manifest.'=>'एक वा बढी प्रदान गरिएका फाइलहरू अब manifest सँग मेल खाँदैनन्।','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'यो साइटका लागि एकपटकको खरिद: %1$s %2$s। भविष्यका सबै अनुवाद अपडेटहरू समावेश छन्। भुक्तानी नयाँ ट्याबमा Paddle ले ह्यान्डल गर्छ।','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'यो काम नेटवर्क प्रशासकले मात्र गर्न सक्छन्, किनभने यसले यस नेटवर्कका सबै साइटहरूले साझा रूपमा प्रयोग गर्ने अनुवाद फाइलहरू परिवर्तन गर्छ।','Only plugins and themes can be packaged.'=>'प्लगइन र थिमहरू मात्र प्याकेज गर्न सकिन्छ।','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'WordPress.org मा नभएको प्लगइन वा थिमको अपलोड तपाईंले पुष्टि गर्दा मात्र: सामान्य गोप्य फाइलका नामसँग मेल खाने फाइलहरू छाडेर, हरेक .php र .js फाइल, हरेक block.json फाइल, र त्यस कम्पोनेन्टको मुख्य फोल्डरमा रहेका readme.txt, readme.md, style.css र theme.json लाई zip को रूपमा पठाइन्छ।','Open Babilim settings'=>'Babilim सेटिङहरू खोल्नुहोस्','Original language'=>'मूल भाषा','Original string'=>'मूल स्ट्रिङ','Paid'=>'सशुल्क','Partner'=>'साझेदार','Please check that your site can be reached from the internet, then try again.'=>'कृपया तपाईंको साइट इन्टरनेटबाट पहुँचयोग्य छ भनी जाँच गर्नुहोस्, अनि फेरि प्रयास गर्नुहोस्।','Please choose a category for this report.'=>'कृपया यो रिपोर्टको लागि वर्ग छान्नुहोस्।','Plugin'=>'प्लगइन','Plugin · %s'=>'प्लगइन · %s','Plugins'=>'प्लगइनहरू','Preview'=>'पूर्वावलोकन गर्नुहोस्','Purchase restored. This site is now licensed.'=>'खरिद पुनर्स्थापना भयो। अब यो साइट इजाजतपत्र प्राप्त छ।','Re-parsed entry count did not match the built index.'=>'पुनः पार्स गरिएको प्रविष्टि सङ्ख्या निर्माण गरिएको सूचीसँग मेल खाएन।','Re-verify'=>'पुनः प्रमाणित गर्नुहोस्','Rebuild index now'=>'सूचकांक अहिले पुनर्निर्माण गर्नुहोस्','Refusing to write outside the Babilim language-file directory.'=>'Babilim भाषा-फाइल डाइरेक्टरी बाहिर लेख्न अस्वीकार गरियो।','Registration response was missing required fields.'=>'दर्ता प्रतिक्रियामा आवश्यक फिल्डहरू छुटेका थिए।','Registration restarted.'=>'दर्ता पुनः सुरु गरियो।','Remove'=>'हटाउनुहोस्','Remove everything Babilim installed'=>'Babilim ले स्थापना गरेका सबै कुरा हटाउनुहोस्','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Babilim ले स्थापना गरेका सबै कुरा हटाउने हो? यसले यस साइटका सबै प्लगइन र थिमका लागि Babilim ले स्थापना गरेका सबै भाषा फाइलहरू मेटाउँछ।','Remove the %2$s translation of %1$s from this site?'=>'यस साइटबाट %1$s को %2$s भाषाको अनुवाद हटाउने?','Removed %d installed component.'=>'%d स्थापित कम्पोनेन्ट हटाइयो।' . "\0" . '%d स्थापित कम्पोनेन्टहरू हटाइए।','Removed after a failed integrity check'=>'अखण्डता जाँच असफल भएपछि हटाइयो','Removed.'=>'हटाइयो।','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'यस साइटका सबै प्लगइन र थिमका लागि Babilim ले स्थापना गरेका सबै भाषा फाइलहरू हटाउँछ।','Report a problem'=>'समस्या रिपोर्ट गर्नुहोस्','Report translation'=>'अनुवादबारे रिपोर्ट गर्नुहोस्','Request newer translation'=>'नयाँ अनुवादको अनुरोध गर्नुहोस्','Request translation'=>'अनुवादको अनुरोध गर्नुहोस्','Requestable'=>'अनुरोध गर्न मिल्ने','Requesting…'=>'अनुरोध गर्दै…','Restart registration'=>'दर्ता पुनः सुरु गर्नुहोस्','Restore code'=>'पुनर्स्थापना कोड','Restore purchase'=>'खरिद पुनर्स्थापना गर्नुहोस्','Retry request'=>'अनुरोध पुनः प्रयास गर्नुहोस्','Roll back'=>'रोलब्याक गर्नुहोस्','Roll back and report'=>'रोलब्याक गरी रिपोर्ट गर्नुहोस्','Roll back and send report'=>'रोलब्याक गरी रिपोर्ट पठाउनुहोस्','Roll back the %2$s translation of %1$s to the previous build?'=>'%1$s को %2$s अनुवादलाई अघिल्लो बिल्डमा रोलब्याक गर्ने?','Rolled back and reported.'=>'रोलब्याक गरियो र रिपोर्ट पठाइयो।','Rolled back to the previous build.'=>'अघिल्लो बिल्डमा रोलब्याक गरियो।','Rolled back, but the report could not be sent: %s'=>'रोलब्याक गरियो, तर रिपोर्ट पठाउन सकिएन: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'पूर्वस्थितिमा फर्काउँदा \'%1$s\' (%2$s) ओभरराइट हुनेछ, जुन अहिले अर्को स्थापित कम्पोनेन्ट (%3$s) का लागि प्रदान गरिएको छ; केही पनि परिवर्तन गरिएन।','Rotate-token response was missing site_token.'=>'टोकन परिवर्तन प्रतिक्रियामा site_token छुटेको थियो।','Save changes'=>'परिवर्तनहरू सुरक्षित गर्नुहोस्','Scheduled, waiting to be processed'=>'अनुसूचित, प्रशोधनको प्रतीक्षामा','Search'=>'खोज्नुहोस्','Search components'=>'कम्पोनेन्टहरू खोज्नुहोस्','Search the installed translations'=>'स्थापना गरिएका अनुवादहरू खोज्नुहोस्','Select all'=>'सबै चयन गर्नुहोस्','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'कम्पोनेन्टहरू कम चयन गर्नुहोस्: प्रत्येक रनमा बढीमा %1$d कार्यहरू (तपाईंले %2$d चयन गर्नुभयो)।','Send report'=>'रिपोर्ट पठाउनुहोस्','Service plan'=>'सेवा योजना','Settings'=>'सेटिङहरू','Share error reports'=>'त्रुटि रिपोर्टहरू साझा गर्नुहोस्','Share this report'=>'यो रिपोर्ट साझा गर्नुहोस्','Show a new restore code'=>'नयाँ पुनर्स्थापना कोड देखाउनुहोस्','Show the "Report translation" entry in the admin toolbar'=>'एडमिन टुलबारमा "अनुवादबारे रिपोर्ट गर्नुहोस्" प्रविष्टि देखाउनुहोस्','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'यस कम्पोनेन्टका केही पाठ यसका लेखकद्वारा हार्ड-कोड गरिएको छ र भाषा प्याकबाट अनुवाद गर्न सकिँदैन।','Status'=>'स्थिति','Status unknown'=>'स्थिति अज्ञात','String context'=>'स्ट्रिङको सन्दर्भ','Suggested translation'=>'सुझाव गरिएको अनुवाद','Supplementary translation index'=>'पूरक अनुवाद सूचकांक','Supplementary translation index rebuilt.'=>'पूरक अनुवाद सूचकांक पुनः निर्माण गरियो।','Supplementary translation maintenance'=>'पूरक अनुवाद मर्मतसम्भार','Supplementary translations'=>'पूरक अनुवादहरू','Sweep aborted without orphaning anything: %s.'=>'केही पनि अनाथ नबनाई सफाइ रोकियो: %s।','Sweep complete: %d file deleted.'=>'सफाइ सम्पन्न भयो: %d फाइल मेटाइयो।' . "\0" . 'सफाइ सम्पन्न भयो: %d फाइलहरू मेटाइए।','Sweep now'=>'अहिले सफा गर्नुहोस्','Sync complete.'=>'सिङ्क पूरा भयो।','Thank you. Your report was sent.'=>'धन्यवाद। तपाईंको रिपोर्ट पठाइयो।','That component is not installed on this site, so a translation cannot be requested for it.'=>'त्यो कम्पोनेन्ट यो साइटमा इन्स्टल गरिएको छैन, त्यसैले यसका लागि अनुवादको अनुरोध गर्न सकिँदैन।','That does not look like a restore code.'=>'यो पुनर्स्थापना कोड जस्तो देखिँदैन।','That is not a valid WordPress locale code. Nothing was saved.'=>'यो मान्य WordPress लोकेल कोड होइन। केही पनि सुरक्षित गरिएन।','That is not a valid build identifier.'=>'त्यो मान्य बिल्ड पहिचानकर्ता होइन।','The change could not be recorded in the translation index; please try again.'=>'परिवर्तन अनुवाद सूचकांकमा रेकर्ड गर्न सकिएन; कृपया फेरि प्रयास गर्नुहोस्।','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'सफाइ चल्यो, तर यसका केही परिवर्तनहरू अनुवाद सूचकांकमा रेकर्ड गर्न सकिएन; अर्को सफाइले ती पुनः प्रयास गर्नेछ।','The component has no files that can be uploaded.'=>'यो कम्पोनेन्टमा अपलोड गर्न मिल्ने कुनै फाइल छैन।','The component is not inside the plugins or themes directory.'=>'कम्पोनेन्ट प्लगइन वा थिम डाइरेक्टरीभित्र छैन।','The component\'s main file was not found.'=>'कम्पोनेन्टको मुख्य फाइल फेला परेन।','The download response was missing a usable location.'=>'डाउनलोड प्रतिक्रियामा प्रयोग गर्न मिल्ने स्थान छुटेको थियो।','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'यो प्रविष्टिले Babilim ले यस साइटमा स्थापना गरेका अनुवादहरू खोज्न र तिनमध्ये कुनै एकबारे रिपोर्ट गर्न एउटा प्यानल खोल्छ।','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'"%1$s" फिल्ड धेरै लामो छ: यसमा %2$d अक्षर छन् र सीमा %3$d हो। केही पठाइएन; कृपया यसलाई छोटो बनाएर फेरि प्रयास गर्नुहोस्।','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'दिइएको डोमेन \'%1$s\' प्याकेज म्यानिफेस्टको आफ्नै स्लग \'%2$s\' वा यसको text_domain \'%3$s\' कुनैसँग मेल खाँदैन।','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'\'%s\' को मर्ज गरिएको सूचकांक पुनः बनाइयो, तर अनुवाद सूचकांकले यसलाई रेकर्ड गर्न सकेन; अर्को पुनर्निर्माणले पुनः प्रयास गर्नेछ।','The original text and the translations made from it will be provided to other sites that install the same version.'=>'मूल पाठ र यसबाट बनाइएका अनुवादहरू उही संस्करण स्थापना गर्ने अन्य साइटहरूलाई उपलब्ध गराइनेछ।','The package declares no main translation file.'=>'प्याकेजले कुनै मुख्य अनुवाद फाइल घोषणा गरेको छैन।','The package has no %s for its own text domain.'=>'प्याकेजमा यसको आफ्नै टेक्स्ट डोमेनका लागि %s छैन।','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'प्याकेज म्यानिफेस्टको प्रकार \'%1$s\' अनुरोध गरिएको प्रकार \'%2$s\' सँग मेल खाँदैन।','The package produced no servable main translation file.'=>'प्याकेजले प्रदान गर्न मिल्ने कुनै मुख्य अनुवाद फाइल उत्पादन गरेन।','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'प्याकेजको टेक्स्ट डोमेन \'%1$s\' यस साइटमा रहेको कम्पोनेन्टको प्रतिलिपि (\'%2$s\') सँग मेल खाँदैन, त्यसैले स्थापना गरिएन।','The packaged component could not be read.'=>'प्याकेज गरिएको कम्पोनेन्ट पढ्न सकिएन।','The registration challenge is not in the expected form.'=>'दर्ता चुनौती अपेक्षित रूपमा छैन।','The report could not be sent.'=>'रिपोर्ट पठाउन सकिएन।','The search could not be completed.'=>'खोज पूरा गर्न सकिएन।','The service asked this site to wait before syncing again.'=>'सेवाले यो साइटलाई फेरि सिन्क गर्नु अघि पर्खन आग्रह गर्‍यो।','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'सेवाले तपाईंको साइटमा पुग्न सकेन। फायरवाल, सुरक्षा प्लगइन वा होस्टको नियमले अनुरोध रोकिरहेको हुन सक्छ; कृपया /wp-json/babilim/v1/challenge मा अनुरोधहरूलाई अनुमति दिनुहोस्।','The service\'s upload offer was incomplete.'=>'सेवाको अपलोड प्रस्ताव अपूर्ण थियो।','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'टेक्स्ट डोमेन \'%1$s\' (%2$s) अर्को स्थापित कम्पोनेन्ट (%3$s) का लागि पहिले नै प्रदान गरिएको छ; केही पनि स्थापना गरिएन।','The upload is kept until you ask Babilim to delete it.'=>'तपाईंले Babilim लाई मेटाउन नभनेसम्म अपलोड राखिन्छ।','Theme'=>'थिम','Theme · %s'=>'थिम · %s','Themes'=>'थिमहरू','There is no upload in progress.'=>'कुनै अपलोड प्रगतिमा छैन।','There is no upload waiting for confirmation.'=>'पुष्टिको प्रतीक्षामा कुनै अपलोड छैन।','These are the languages this site uses. You can change them in %s.'=>'यी यो साइटले प्रयोग गर्ने भाषाहरू हुन्। तपाईं यिनलाई %s मा परिवर्तन गर्न सक्नुहुन्छ।','These fields will be sent:'=>'यी फिल्डहरू पठाइनेछन्:','This build is not one this site currently knows about for this component/locale.'=>'यो बिल्ड यो कम्पोनेन्ट/लोकेलका लागि यस साइटले हाल चिनेको बिल्ड होइन।','This component does not declare a version number, so a translation cannot be requested for it.'=>'यो कम्पोनेन्टले संस्करण नम्बर घोषणा गरेको छैन, त्यसैले यसका लागि अनुवादको अनुरोध गर्न सकिँदैन।','This component is larger than the service accepts, so it cannot be uploaded.'=>'यो कम्पोनेन्ट सेवाले स्वीकार गर्ने भन्दा ठूलो छ, त्यसैले अपलोड गर्न सकिँदैन।','This component was already uploaded. Babilim is checking it now.'=>'यो कम्पोनेन्ट पहिले नै अपलोड गरिएको थियो। Babilim ले अहिले यसको जाँच गर्दैछ।','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'यो कम्पोनेन्टको संस्करण नम्बर %d अक्षरभन्दा लामो छ, जुन Babilim ले सम्हाल्न सक्दैन, त्यसैले यसका लागि अनुवादको अनुरोध गर्न सकिँदैन।','This issues a new restore code and the previous one stops working. Continue?'=>'यसले नयाँ पुनर्स्थापना कोड जारी गर्छ र अघिल्लो कोडले काम गर्न छोड्छ। जारी राख्ने?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'यस नेटवर्कमा साइटहरू एक-एक गरी जाँच गर्न धेरै छन्, र तीमध्ये केही प्लगइन मेटाउँदा आफ्नो Babilim पहिचान मेटाउने गरी सेट गरिएका हुन सक्छन्। त्यस्तो साइटमा जोडिएको सशुल्क इजाजतपत्र त्यसपछि स्वतः पुनःप्राप्त गर्न सकिँदैन; तपाईंले %s मा Babilim सहायतासँग सम्पर्क गर्नुपर्नेछ। पहिचानहरू राख्न, रद्द गर्नुहोस् थिच्नुहोस्, प्रत्येक साइटको Babilim सेटिङहरूमा "अनइन्स्टल गर्दा सबै Babilim डेटा मेटाउनुहोस्" को चिह्न हटाउनुहोस्, र फेरि निष्क्रिय गर्नुहोस्। जे भए पनि निष्क्रिय गर्ने?','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'यस प्लगइनको आफ्नै संस्करण, ताकि यो सेवासँग सञ्चार गर्न धेरै पुरानो भएमा सेवाले तपाईंलाई अपडेट गर्न भन्न सकोस्।','This report does not name a valid plugin or theme and locale.'=>'यो रिपोर्टले मान्य प्लगइन वा थिम र लोकेल उल्लेख गरेको छैन।','This report does not name an installed string.'=>'यो रिपोर्टले स्थापना गरिएको कुनै स्ट्रिङको नाम उल्लेख गर्दैन।','This report is missing a valid build to report against.'=>'यो रिपोर्टमा रिपोर्ट गर्नका लागि मान्य बिल्ड छैन।','This report will be posted publicly on GitHub and may be kept by third parties.'=>'यो रिपोर्ट GitHub मा सार्वजनिक रूपमा पोस्ट गरिनेछ र तेस्रो पक्षहरूले यसलाई राख्न सक्छन्।','This restore code was not recognised for this site.'=>'यो पुनर्स्थापना कोड यस साइटका लागि पहिचान भएन।','This site already has an active registration that can no longer be recovered automatically.'=>'यो साइटमा पहिल्यै सक्रिय दर्ता छ जुन अब स्वचालित रूपमा पुनः प्राप्त गर्न सकिँदैन।','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'यो साइटमा %2$d भाषाहरूमा %1$d कम्पोनेन्टहरू छन्, जसका लागि %3$d जाँच ब्याचहरू आवश्यक पर्छन्; Babilim ले प्रत्येक रनमा बढीमा %4$d ह्यान्डल गर्न सक्छ। सेटिङहरूमा व्यवस्थापन गरिएका भाषाहरू घटाउनुहोस् वा प्रयोग नगरिएका प्लगइन र थिमहरू निष्क्रिय गर्नुहोस्, त्यसपछि अहिले फेरि जाँच गर्नुहोस् थिच्नुहोस्।','This site has no purchase to show a code for.'=>'यो साइटमा कोड देखाउनका लागि कुनै खरिद छैन।','This site is already licensed. Reload the page.'=>'यो साइटसँग पहिल्यै इजाजतपत्र छ। पृष्ठ पुनः लोड गर्नुहोस्।','This site is not registered with Babilim yet.'=>'यो साइट अहिलेसम्म Babilim मा दर्ता गरिएको छैन।','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'यो साइट एकपटकको सिङ्कमा सेवाले स्वीकार गर्ने आकारभन्दा ठूलो छ, त्यसैले केही वस्तुहरू छुटे: %1$d कम्पोनेन्ट र %2$d लोकेल।','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'यो साइट मल्टिसाइट नेटवर्कको हिस्सा हो, जसले नयाँ अनुवादहरू स्वचालित रूपमा स्थापना गर्दैन। पहिल्यै स्थापना भइसकेका अनुवादहरू भने अझै अपडेट हुन्छन्।','This site is verified.'=>'यो साइट प्रमाणित भएको छ।','This site must be verified first.'=>'यो साइट पहिले प्रमाणित गरिनुपर्छ।','This site\'s URL, so the service can verify you own it.'=>'यो साइटको URL, ताकि सेवाले तपाईं यसको मालिक हुनुहुन्छ भनी प्रमाणित गर्न सकोस्।','This site\'s address is too long for Babilim to register.'=>'यो साइटको ठेगाना Babilim मा दर्ता गर्न धेरै लामो छ।','This site\'s configured locale.'=>'यस साइटको कन्फिगर गरिएको लोकेल।','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'यस साइटको स्थापना सार्वजनिक कुञ्जी, अनुरोधहरू साँच्चै यही साइटबाट आएका हुन् भनी प्रमाणित गर्न प्रयोग गरिन्छ। केवल सार्वजनिक भाग मात्र पठाइन्छ।','This site\'s locale code is not one Babilim can register.'=>'यो साइटको लोकेल कोड Babilim ले दर्ता गर्न सक्ने कोड होइन।','This string can\'t be reported from this site.'=>'यो स्ट्रिङ यस साइटबाट रिपोर्ट गर्न सकिँदैन।','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'यो स्ट्रिङ यस साइटमा स्थापना गरिएका अनुवादहरूमा छैन। फेरि खोज्नुहोस् र सूचीबाट छान्नुहोस्।','This translation was updated since you searched. Search again and pick the string from the new list.'=>'तपाईंले खोजेपछि यो अनुवाद अद्यावधिक गरिएको छ। फेरि खोज्नुहोस् र नयाँ सूचीबाट स्ट्रिङ छान्नुहोस्।','To translate this component, Babilim needs its source.'=>'यो कम्पोनेन्ट अनुवाद गर्न Babilim लाई यसको स्रोत चाहिन्छ।','Too many attempts. Try again tomorrow.'=>'धेरै प्रयासहरू भए। भोलि फेरि प्रयास गर्नुहोस्।','Too many reports today. Try again tomorrow.'=>'आज धेरै रिपोर्टहरू भए। भोलि फेरि प्रयास गर्नुहोस्।','Too many requests.'=>'धेरै अनुरोधहरू।','Toolbar'=>'टुलबार','Translating…'=>'अनुवाद गरिँदैछ…','Translation does not load'=>'अनुवाद लोड हुँदैन','Translation failed'=>'अनुवाद असफल भयो','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'तपाईंले %s मा राखेका अनुवाद फाइलहरूले सधैं Babilim का फाइलहरूभन्दा प्राथमिकता पाउँछन्। यसलाई अनचेक नगरेसम्म ती राखिन्छन्।','Translation requested.'=>'अनुवादको अनुरोध गरियो।','Translations'=>'अनुवादहरू','Type'=>'प्रकार','Type at least 2 characters to search.'=>'खोज्न कम्तीमा २ वटा अक्षर टाइप गर्नुहोस्।','Unexpected HTTP %d response.'=>'अप्रत्याशित HTTP %d प्रतिक्रिया।','Uninstall'=>'अनइन्स्टल','Unknown kind: %s'=>'अज्ञात प्रकार: %s','Unsafe domain: %s'=>'असुरक्षित डोमेन: %s','Unsafe locale: %s'=>'असुरक्षित लोकेल: %s','Unsafe slug: %s'=>'असुरक्षित स्लग: %s','Unsafe text_domain: %s'=>'असुरक्षित text_domain: %s','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'२० सम्म विचाराधीन निदान घटनाहरू (जस्तै अखण्डता जाँचमा असफल भएको फाइल), प्रत्येकमा केवल कोड, कम्पोनेन्ट र लोकेल हुन्छ, र कुनै पनि स्ट्रिङ सामग्री वा अनुवादित पाठ कहिल्यै हुँदैन।','Update'=>'अद्यावधिक गर्नुहोस्','Update available'=>'अद्यावधिक उपलब्ध छ','Updates'=>'अद्यावधिकहरू','Updating…'=>'अद्यावधिक गर्दै…','Upgrade this site'=>'यो साइट अपग्रेड गर्नुहोस्','Upload and request'=>'अपलोड गरी अनुरोध गर्नुहोस्','Upload cancelled.'=>'अपलोड रद्द गरियो।','Upload complete — translation requested.'=>'अपलोड सम्पन्न — अनुवादको अनुरोध गरियो।','Upload expired before it finished'=>'सकिनु अघि नै अपलोडको म्याद सकियो','Upload in progress — continue or cancel'=>'अपलोड हुँदैछ — जारी राख्नुहोस् वा रद्द गर्नुहोस्','Upload this component?'=>'यो कम्पोनेन्ट अपलोड गर्ने?','Upload was not accepted'=>'अपलोड स्वीकार गरिएन','Uploading'=>'अपलोड गर्दै','Uploading part %1$d of %2$d…'=>'%2$d मध्ये भाग %1$d अपलोड गर्दै…','Uploading…'=>'अपलोड गर्दै…','Verified'=>'प्रमाणित भयो','Verify response was missing site_token.'=>'प्रमाणीकरण प्रतिक्रियामा site_token छुटेको थियो।','Version %s'=>'संस्करण %s','What is sent when Babilim checks this site'=>'Babilim ले यो साइट जाँच गर्दा के पठाइन्छ','What is sent when you enable Babilim'=>'Babilim सक्षम गर्दा के पठाइन्छ','When something fails inside Babilim, send an error report to the Babilim service so it can be published as a public issue on GitHub. The report is sent as coming from this site, with the same authentication as every other request to the Babilim service. The service publishes only the error code and versions as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'Babilim भित्र केही असफल हुँदा, Babilim service लाई त्रुटि रिपोर्ट पठाउनुहोस् ताकि यसलाई GitHub मा सार्वजनिक इश्युको रूपमा प्रकाशित गर्न सकियोस्। रिपोर्ट यही साइटबाट आएको रूपमा पठाइन्छ, Babilim service मा जाने अन्य हरेक अनुरोधमा जस्तै उही प्रमाणीकरणसहित। सेवाले त्रुटि कोड र संस्करणहरू मात्र GitHub मा सार्वजनिक इश्युको रूपमा प्रकाशित गर्छ; सार्वजनिक इश्युमा साइटको ठेगाना, सामग्री वा फाइल पथहरू हुँदैनन्। पूर्वनिर्धारित रूपमा बन्द।','Where you saw this (optional)'=>'तपाईंले यो कहाँ देख्नुभयो (ऐच्छिक)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'यो सक्रिय हुँदा, तपाईंले व्यवस्थापन गर्ने भाषाहरूका लागि सेवाले उपलब्ध भनी सूचीबद्ध गरेका अनुवादहरू दिनमा दुई पटक हुने सिङ्कको समयमा स्थापना गरिन्छन्।','WordPress.org'=>'WordPress.org','Wrong for this context'=>'यस सन्दर्भका लागि गलत','Wrong meaning'=>'गलत अर्थ','Wrong plural form'=>'गलत बहुवचन रूप','Wrong term'=>'गलत शब्द','Yes'=>'हो','You are not allowed to do this.'=>'तपाईंलाई यो गर्न अनुमति छैन।','Your PHP version, for compatibility.'=>'तपाईंको PHP संस्करण, अनुकूलताका लागि।','Your WordPress version, to serve compatible translation files.'=>'तपाईंको WordPress संस्करण, ताकि उपयुक्त अनुवाद फाइलहरू उपलब्ध गराउन सकियोस्।','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'तपाईंको नयाँ पुनर्स्थापना कोड: %s। यसलाई सुरक्षित ठाउँमा राख्नुहोस् — अघिल्लो कोडले अब काम गर्दैन।','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'तपाईंको रिपोर्ट AI मोडेलहरूद्वारा स्वचालित रूपमा प्रशोधन गरिन्छ र अन्य साइटहरूका लागि यो अनुवाद सुधार्न सक्छ।','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'तपाईंको साइटले जवाफ दियो, तर अपेक्षित जवाफ दिएन। अर्को प्लगइनले REST API लाई परिवर्तन गरिरहेको हुन सक्छ, वा त्यो एन्डपोइन्ट क्यास गरिएको हुन सक्छ; कृपया /wp-json/babilim/v1/challenge लाई क्यास र पुनर्लेखनबाट बाहिर राख्नुहोस्।','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'तपाईंको साइटले जवाफ दिन धेरै समय लियो। कृपया पछि फेरि प्रयास गर्नुहोस्, र तपाईंको होस्ट धेरै ढिलो वा ओभरलोड भएको छैन भनी जाँच गर्नुहोस्।','Zip has no manifest.json.'=>'Zip मा manifest.json छैन।','Zip is missing expected default file: %s'=>'जिपमा अपेक्षित पूर्वनिर्धारित फाइल हराइरहेको छ: %s','Zip is missing expected file: %s'=>'जिपमा अपेक्षित फाइल हराइरहेको छ: %s','_manifest.json has an unexpected structure'=>'_manifest.json को संरचना अप्रत्याशित छ','could not read _manifest.json: %s'=>'_manifest.json पढ्न सकिएन: %s','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest हराइरहेको छ वा यसमा अमान्य \'%s\' छ।','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'expected_manifest को \'server_build_id\' मान्य बिल्ड आईडी होइन।','failed to parse _manifest.json: %s'=>'_manifest.json पार्स गर्न असफल भयो: %s','it would orphan %1$d of %2$d managed components (more than half)'=>'यसले %2$d व्यवस्थित कम्पोनेन्टहरू मध्ये %1$d लाई अनाथ बनाउनेछ (आधाभन्दा बढी)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'यसले %2$d मध्ये %2$d सबै व्यवस्थित %1$s कम्पोनेन्टलाई अनाथ बनाउनेछ','l10n.php entry count mismatch for %s'=>'%s को l10n.php प्रविष्टि संख्या मेल खाएन','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json मा अमान्य \'default_domain_entries\' छ।','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json मा अमान्य \'default_domain_files\' छ।','manifest.json in the zip is not valid JSON.'=>'zip भित्रको manifest.json मान्य JSON होइन।','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json मा \'%s\' छैन वा अमान्य छ।','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json मा \'build_no\' छैन वा अमान्य छ।','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json मा \'entries\' छैन वा अमान्य छ।','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json मा \'extra_domains\' छैन वा अमान्य छ।','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json मा \'files\' छैन वा अमान्य छ।','manifest.json\'s \'%s\' does not match the expected value.'=>'manifest.json को \'%s\' अपेक्षित मानसँग मेल खाँदैन।','manifest.json\'s \'contract\' is not a valid version string.'=>'manifest.json को \'contract\' मान्य संस्करण स्ट्रिङ होइन।','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'manifest.json मा \'kind\' को मान \'plugin\' वा \'theme\' मध्ये एउटा हुनुपर्छ।','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'manifest.json को \'server_build_id\' मान्य बिल्ड आईडी होइन।','manifest.json\'s \'status\' must be \'published\'.'=>'manifest.json को \'status\' मान \'published\' नै हुनुपर्छ।','nonce must be a hexadecimal string.'=>'नन्स हेक्साडेसिमल स्ट्रिङ हुनुपर्छ।','per day'=>'प्रति दिन','rc_…'=>'rc_…','sha256 mismatch for %s'=>'%s को sha256 मेल खाएन','sha256 mismatch for default/%s'=>'default/%s को sha256 मेल खाएन','component kind in the sweep brake messageplugin'=>'प्लगइन','component kind in the sweep brake messagetheme'=>'थिम','problem report categoryOther'=>'अन्य','translation statusAvailable'=>'उपलब्ध','translation statusInstalled'=>'स्थापना गरिएको']];